export async function getJSON(path) {
  const response = await fetch(path, {
    headers: {
      Accept: "application/json",
    },
  });
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  return response.json();
}

export async function getFastApiJSON(path) {
  // FastAPI server exposes quote endpoints (fastapi_server/main.py -> /api/quote).
  // In many local setups Django runs on :8000 and FastAPI on :8001.
  // We support both with fallback to reduce 404 issues.
  const configured = process.env.REACT_APP_FASTAPI_HTTP_BASE;
  const candidateBases = configured
    ? [configured]
    : ["http://127.0.0.1:8001", "http://127.0.0.1:8000"];

  const requestPath = path.startsWith("http") ? path : null;
  let lastError = null;

  for (const base of candidateBases) {
    const url = requestPath || `${base}${path}`;
    try {
      const response = await fetch(url, {
        headers: {
          Accept: "application/json",
        },
      });

      if (!response.ok) {
        // Try next base if this host doesn't serve FastAPI endpoints.
        lastError = new Error(`Request failed: ${response.status} (${url})`);
        continue;
      }
      return response.json();
    } catch (error) {
      lastError = error;
    }
  }

  throw lastError || new Error("Request failed on all configured FastAPI bases");
}
